 let content='';
 if(step==='welcome')content=`<div class="auth-welcome">${logo}<div class="auth-welcome-copy"><span class="eyebrow">YOUR NEXT CHAPTER</span><h1>Learn<br>Grow<br><span class="accent">Get Placed</span></h1><p>Build practical skills.<br>Take your next step with confidence.</p><ul><li>Live & recorded learning paths</li><li>Hands-on project practice</li><li>Career-focused learning</li></ul></div><img src="assets/hero.jpeg" alt="Learner pictured in the supplied Tura design reference"></div><div class="auth-welcome-actions"><a class="button" href="#auth/signin">Sign in</a><a class="button secondary" href="#auth/role">Create an account</a></div>`;
 else if(step==='role')content=back+logo+title('Create your account','Choose how you want to join.')+`<div class="auth-roles"><a href="#auth/signup" class="auth-role"><span>◇</span><div><b>I’m a Student</b><small>Learn new skills and advance your career.</small></div><strong>›</strong></a><button type="button" class="auth-role" data-role-preview="trainer"><span>▧</span><div><b>I’m a Trainer</b><small>Teach and share your expertise.</small></div><strong>›</strong></button><button type="button" class="auth-role" data-role-preview="company"><span>▣</span><div><b>I’m a Recruiter / Company</b><small>Explore talent and opportunities.</small></div><strong>›</strong></button></div><p class="auth-bottom">Already have an account? <a href="#auth/signin">Sign in</a></p>`;
