 const hero=(heading,description,c)=>`<div class="catalogue-hero"><div class="catalogue-wrap catalogue-hero-inner"><div><div class="catalogue-eyebrow">${c?'COURSE OVERVIEW':'OUR COURSES'}</div><h1>${heading}</h1><p>${description}</p><div class="catalogue-benefits"><div><span>▧</span>Live & self-paced paths</div><div><span>◇</span>Real-world projects</div><div><span>✦</span>Practical skills</div><div><span>↗</span>Career-focused learning</div></div></div><div class="catalogue-hero-image"><img src="assets/hero.jpeg" alt="Learner with a Tura laptop from the supplied design reference"><div class="catalogue-hero-notes"><div>Explore four learning paths</div><div>Build practical skills</div><div>Learn through projects</div><div>Request a free demo</div></div></div></div></div>`;
 if(isDetail){const c=courses.find(item=>item.id===path[1]);if(!c)return;app.innerHTML=css+hero(escape(c.name),c.desc,c)+`<div class="catalogue-wrap"><div class="course-detail-grid"><div><article class="course-detail-panel"><div class="catalogue-eyebrow">COURSE DETAILS & SYLLABUS</div><h2>Build a clear foundation.</h2><p>Proposed learning outline. Confirm prerequisites, full syllabus, duration, fees and delivery mode with admissions before enrolling.</p>${c.modules.map((module,index)=>`<details ${index===0?'open':''}><summary>Module ${index+1} · ${module}</summary><p>Explore the foundations of ${module.toLowerCase()} with guided examples and practical exercises. Detailed lesson plans are awaiting confirmation.</p></details>`).join('')}</article><article class="course-detail-panel"><div class="catalogue-eyebrow">LEARNING MODES</div><h2>A path that fits your learning.</h2><h3>Live instructor-led</h3><p>Guided sessions and opportunities to ask questions. Batch schedules and availability need confirmation.</p><h3>Self-paced</h3><p>Independent learning is planned. Recorded lessons, access duration and availability are not connected yet.</p></article><article class="course-detail-panel"><div class="catalogue-eyebrow">STUDENT REVIEWS</div><h2>Learning experiences, in their own words.</h2><div class="course-detail-review">Verified reviews for ${c.name} will appear here after approval. No ratings or student testimonials have been published yet.</div></article><article class="course-detail-panel"><div class="catalogue-eyebrow">COURSE FAQs</div><h2>Your questions, answered.</h2>${[['Do I need prior experience?','Prerequisites depend on your background and the final course syllabus. Request a demo to discuss the right starting point.'],['What are the fees and course duration?','Verified fees, duration and batch dates are awaiting confirmation. Contact admissions through a demo enquiry before enrolling.'],['Can I choose self-paced learning?','Self-paced learning is planned. Confirm whether this course is available in your preferred mode with the team.'],['Will I receive a certificate or placement support?','Certificate requirements and the scope of career support need confirmation. This website does not promise a job or placement.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</article></div><aside><div class="course-detail-panel"><div class="course-detail-art" style="--card-bg:${c.bg};--card-color:${c.color}" aria-hidden="true">${c.icon}</div><h2 style="margin-top:20px">${c.name}</h2><p>Explore the course before you commit.</p><p class="course-detail-subtitle">Fees, schedule & learning mode: to be confirmed</p><div class="actions"><button class="button" data-demo="${c.id}">Book a free demo ↗</button><button class="button secondary" data-add="${c.id}">Add to bag</button></div><a class="text-link" href="#courses">← All courses</a></div></aside></div></div>`;document.title=`${c.name} — Tura Infotech`;return}
