 app.innerHTML=css+`<div class="help-hero"><div class="help-wrap help-hero-inner"><div><div class="help-eyebrow">SUPPORT & HELP CENTER</div><h1>We’re Here<br><span>to Help You!</span></h1><p>Find guidance, prepare a support request and get clarity on your next step.</p></div><div class="help-hero-art"><img src="assets/hero.jpeg" alt="Learner from the supplied Tura design reference"></div></div></div><div class="help-wrap"><form id="help-search" class="help-search"><input name="query" type="search" aria-label="Search help articles" placeholder="Search for help, course access or payment guidance…" value="${escape(supportQuery)}"><button class="button">Search</button></form><div class="help-shortcuts">${[['articles','▧','Help Center'],['faq','◇','FAQs'],['raise','▣','Raise a Ticket'],['status','▤','Ticket Status'],['channels','◉','Chat / WhatsApp'],['payment','♧','Technical & Payment Help']].map(([key,icon,label])=>`<button class="help-shortcut" data-help-shortcut="${key}"><span aria-hidden="true">${icon}</span><b>${label}</b></button>`).join('')}</div><p class="help-notice">Support preview. Ticket drafts stay in this browser and are not sent to a support team. Verified contact details, WhatsApp, live chat and shared ticket services are not connected.</p><div class="help-layout"><section class="help-panel" id="help-articles"><h2>Help Center</h2><p class="help-result" id="help-result" role="status"></p><div id="help-article-list"></div></section><section class="help-panel" id="help-faq"><h2>Frequently Asked Questions</h2>${questions.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section class="help-panel help-form-panel" id="help-raise"><h2>Raise a Support Ticket</h2><p>Prepare a support request draft. Avoid passwords, OTPs, card numbers and sensitive identity information.</p><form id="help-ticket-form" class="help-form"><label>Subject<input name="title" maxlength="150" required></label><label>Category<select name="category"><option>Learning & courses</option><option>Technical help</option><option>Payments</option><option>Other</option></select></label><label>Message<textarea name="message" maxlength="5000" required></textarea></label><label class="help-check"><input type="checkbox" required><span>I understand this saves a draft locally and does not contact the support team.</span></label><button class="button">Save Ticket Draft ↗</button><p id="help-form-status" role="status"></p></form></section></div><section class="help-channels" id="help-channels"><article class="help-channel"><h2>Chat on WhatsApp</h2><p>A verified support number has not been supplied. WhatsApp support is not connected.</p><button class="button secondary" disabled>WhatsApp unavailable</button></article><article class="help-channel"><h2>Live Chat Support</h2><p>No chat agent service, support hours or response times are connected.</p><button class="button secondary" disabled>Live chat unavailable</button></article><article class="help-channel"><h2>Technical & Payment Help</h2><p>Read troubleshooting guidance or prepare a support draft for your question.</p><button class="button secondary" data-help-shortcut="payment">Browse guidance ↗</button></article></section><section class="help-tickets" id="help-status"><h2>Ticket Status</h2><p class="help-notice">${tickets.length} local draft${tickets.length===1?'':'s'} · no submissions or team responses. These drafts are shared with this browser’s Student Portal support view.</p>${tickets.length?tickets.map(t=>`<article class="help-ticket"><div><h3>${escape(t.title)}</h3><span class="help-badge">${t.closed?'Closed locally':'Draft · not submitted'}</span><small>${escape(t.category)}</small><p>${escape(t.message)}</p></div><button class="button secondary" data-help-toggle="${escape(t.id)}">${t.closed?'Reopen draft':'Close draft'}</button></article>`).join(''):'<div class="help-empty">No support drafts saved yet. Use the form above to prepare a request.</div>'}</section></div>`;
